/**
 * Centres listing handler
 * GET /api/centres - List all configured centres
 */

import type { Env } from '../lib/types';
import { createClient } from '@supabase/supabase-js';

/**
 * Lists all configured centres
 * GET /api/centres
 */
export async function handleListCentres(env: Env): Promise<Response> {
  try {
    const supabase = createClient(env.SUPABASE_URL, env.SUPABASE_SERVICE_KEY);

    const { data: centres, error } = await supabase
      .from('centres')
      .select('id, location_name, timezone, timezone_display, twilio_number, calling_enabled, max_concurrent_calls, active_calls, availability_api_url')
      .order('location_name');

    if (error) {
      console.error('Error fetching centres:', error);
      return new Response(
        JSON.stringify({
          error: 'Database error',
          message: error.message,
        }),
        {
          status: 500,
          headers: { 'Content-Type': 'application/json' },
        }
      );
    }

    return new Response(
      JSON.stringify({
        centres: centres || [],
        count: centres?.length || 0,
      }, null, 2),
      {
        status: 200,
        headers: { 'Content-Type': 'application/json' },
      }
    );
  } catch (error) {
    console.error('Error listing centres:', error);
    return new Response(
      JSON.stringify({
        error: 'Internal server error',
        message: String(error),
      }),
      {
        status: 500,
        headers: { 'Content-Type': 'application/json' },
      }
    );
  }
}

